package main

import (
	"embed"
	"fmt"
	"net/http"
	"net/http/httputil"
	"net/url"
	"strings"

	"github.com/prometheus/client_golang/prometheus"
	"github.com/prometheus/client_golang/prometheus/promhttp"
	"go.yaml.in/yaml/v4"
)

//go:embed ui
var assets embed.FS

type fixtureConfig struct {
	Name string `yaml:"name"`
}

func decodeFixture(input string) (fixtureConfig, error) {
	var c fixtureConfig
	dec := yaml.NewDecoder(strings.NewReader(input))
	dec.KnownFields(true)
	err := dec.Decode(&c)
	return c, err
}

func fixtureMetrics() http.Handler {
	registry := prometheus.NewRegistry()
	gauge := prometheus.NewGauge(prometheus.GaugeOpts{Name: "fixture_capacity", Help: "Synthetic capacity"})
	registry.MustRegister(gauge)
	gauge.Set(5)
	return promhttp.HandlerFor(registry, promhttp.HandlerOpts{})
}

func main() {
	if _, err := decodeFixture("name: fixture\n"); err != nil {
		panic(err)
	}
	if _, err := assets.ReadFile("ui/index.html"); err != nil {
		panic(err)
	}
	proxyURL, err := url.Parse("socks5h://127.0.0.1:1080")
	if err != nil {
		panic(err)
	}
	transport := &http.Transport{Proxy: http.ProxyURL(proxyURL)}
	_ = &httputil.ReverseProxy{Transport: transport}
	_ = fixtureMetrics()
	fmt.Println("fixture build ok; no network dispatch")
}

