package main

import (
	"net/http/httptest"
	"strings"
	"testing"
)

func TestYAMLStrictCompatibility(t *testing.T) {
	for _, tc := range []struct {
		name, body string
		wantError  bool
	}{
		{"valid", "name: fixture\n", false},
		{"unknown field", "name: fixture\nunexpected: true\n", true},
		{"duplicate key", "name: fixture\nname: other\n", true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			_, err := decodeFixture(tc.body)
			if (err != nil) != tc.wantError {
				t.Fatalf("error=%v, wantError=%v", err, tc.wantError)
			}
		})
	}
}

func TestPrometheusRegistryCompatibility(t *testing.T) {
	w := httptest.NewRecorder()
	fixtureMetrics().ServeHTTP(w, httptest.NewRequest("GET", "/metrics", nil))
	if w.Code != 200 || !strings.Contains(w.Body.String(), "fixture_capacity 5") {
		t.Fatalf("unexpected metrics: status %d", w.Code)
	}
}

func TestEmbeddedBuildArtifact(t *testing.T) {
	data, err := assets.ReadFile("ui/index.html")
	if err != nil || !strings.Contains(string(data), "Fixture M0") {
		t.Fatalf("embedded UI missing: %v", err)
	}
}
